S = "Hakeem Force Academy"
QS = [
(S, "How many inches are in one foot?", ["10", "12", "14", "16"], 1, "One foot is defined as 12 inches.", "One yard is 3 feet, which equals 36 inches.", [198]),
(S, "What is the full form of GDP?", ["Gross Domestic Product", "General Domestic Production", "Gross Departmental Profit", "Grand Domestic Price"], 0, "GDP stands for Gross Domestic Product, the total value of goods and services produced in a country in a year.", "GNP (Gross National Product) also counts income earned by citizens abroad.", [451]),
(S, "What is the full form of NEPRA in Pakistan?", ["National Electric Power Regulatory Authority", "National Energy Production and Research Agency", "National Electricity Pricing and Revenue Authority", "Nuclear Energy Power Regulation Agency"], 0, "NEPRA stands for National Electric Power Regulatory Authority, which regulates the power sector of Pakistan.", "NEPRA was established in 1997 and its head office is in Islamabad.", [453]),
(S, "Where is the headquarters of the National Radio and Telecommunication Corporation (NRTC) of Pakistan?", ["Lahore", "Karachi", "Haripur", "Rawalpindi"], 2, "NRTC is a defence production organisation based in Haripur, Khyber Pakhtunkhwa.", "In 2021 the government handed Telephone Industries of Pakistan over to NRTC.", [554]),
(S, "Who designed the national flag of Pakistan according to most Pakistani sources?", ["Syed Amiruddin Kidwai", "Allama Iqbal", "Chaudhry Rehmat Ali", "Liaquat Ali Khan"], 0, "The flag was designed by Syed Amiruddin Kidwai, based on the flag of the All India Muslim League, and adopted on 11 August 1947.", "Some sources also mention Master Altaf Hussain as the one who prepared the first flag, so sources differ.", [128]),
(S, "A helicopter uses 120 gallons of fuel to travel 60 km. How far will it travel on 700 gallons at the same rate?", ["250 km", "300 km", "350 km", "420 km"], 2, "Distance per gallon is 60 / 120 = 0.5 km. So 700 gallons cover 700 x 0.5 = 350 km.", "This is a direct proportion question: more fuel gives more distance.", [138, 143]),
(S, "Who gave the Six Points formula of 1966 demanding autonomy for East Pakistan?", ["Maulana Bhashani", "Sheikh Mujibur Rahman", "H. S. Suhrawardy", "A. K. Fazlul Huq"], 1, "Sheikh Mujibur Rahman presented the Six Points at a conference of opposition parties in Lahore in February 1966.", "The Six Points became the base of the Awami League movement that led to Bangladesh in 1971.", [664]),
(S, "Who imposed martial law in Pakistan in July 1977?", ["General Yahya Khan", "General Ayub Khan", "General Zia-ul-Haq", "General Pervez Musharraf"], 2, "General Zia-ul-Haq overthrew Prime Minister Zulfikar Ali Bhutto on 5 July 1977 and imposed martial law.", "The operation was called Operation Fair Play.", [668]),
(S, "In which year was UNESCO founded?", ["1945", "1948", "1950", "1955"], 0, "UNESCO was founded in 1945 when its constitution was adopted in London, as the United Nations agency for education, science and culture.", "Its constitution came into force in November 1946 and its headquarters is in Paris.", [547]),
(S, "On which date is Human Rights Day observed every year?", ["10 December", "10 October", "24 October", "1 December"], 0, "Human Rights Day is observed on 10 December, the day the UN General Assembly adopted the Universal Declaration of Human Rights in 1948.", "24 October is United Nations Day.", [442]),
(S, "After which pact was Quaid-e-Azam Muhammad Ali Jinnah called the Ambassador of Hindu-Muslim Unity?", ["Lucknow Pact", "Nehru Report", "Gandhi-Irwin Pact", "Simla Agreement"], 0, "Jinnah worked to bring the Muslim League and Congress together in the Lucknow Pact of 1916, and was then called the Ambassador of Hindu-Muslim Unity.", "The title is commonly credited to Sarojini Naidu.", [55]),
(S, "Minar-e-Pakistan in Lahore commemorates which historical event?", ["Lahore Resolution of 1940", "War of Independence 1857", "Independence on 14 August 1947", "Lucknow Pact of 1916"], 0, "Minar-e-Pakistan was built at Iqbal Park (Minto Park) to mark the passing of the Lahore Resolution on 23 March 1940.", "Its construction was completed in 1968.", [316, 83]),
(S, "Who was the Viceroy of India at the time of the 3rd June Plan of 1947?", ["Lord Wavell", "Lord Linlithgow", "Lord Mountbatten", "Lord Irwin"], 2, "Lord Mountbatten, the last Viceroy, announced the 3rd June Plan which proposed the partition of India.", "He became the first Governor General of independent India after independence.", [734]),
(S, "The Jallianwala Bagh massacre of 1919 took place in protest against which act?", ["Rowlatt Act", "Pitt's India Act", "Vernacular Press Act", "Government of India Act 1935"], 0, "People gathered in Amritsar to protest the Rowlatt Act, which allowed arrest without trial, and General Dyer fired on them.", "The massacre took place on 13 April 1919.", [359]),
(S, "Who was the Viceroy of India at the time of the Jallianwala Bagh massacre in 1919?", ["Lord Curzon", "Lord Chelmsford", "Lord Minto", "Lord Reading"], 1, "Lord Chelmsford was Viceroy and Governor General of India from 1916 to 1921.", "Lord Reading succeeded him in 1921.", [721]),
(S, "Who is the author of the book Jinnah of Pakistan?", ["Stanley Wolpert", "Hector Bolitho", "Akbar S. Ahmed", "Ayesha Jalal"], 0, "Jinnah of Pakistan (1984) was written by the American historian Stanley Wolpert.", "Hector Bolitho wrote Jinnah: Creator of Pakistan.", [742]),
(S, "What was the original name of the Mughal emperor Jahangir?", ["Prince Khurram", "Prince Salim", "Prince Murad", "Prince Dara"], 1, "Jahangir was born as Prince Salim (Nur-ud-Din Muhammad Salim) and took the title Jahangir when he became emperor.", "His son Prince Khurram later became Emperor Shah Jahan.", [520]),
(S, "Is Islamabad a proper noun or a common noun?", ["Common noun", "Proper noun", "Abstract noun", "Collective noun"], 1, "Islamabad is the name of one particular city, so it is a proper noun.", "A proper noun always begins with a capital letter.", [77]),
(S, "What is the negative form of a past indefinite (simple past) sentence?", ["Subject + did not + base form of verb", "Subject + does not + base form of verb", "Subject + was not + verb with ing", "Subject + had not + past participle"], 0, "In the simple past, the negative is made with did not plus the first form of the verb, for example: He did not go.", "Past indefinite verbs in the positive use the second form, such as went.", [480]),
(S, "In which year did Pakistan conduct its nuclear tests at Chagai?", ["1996", "1998", "2000", "1999"], 1, "Pakistan carried out its nuclear tests in Chagai, Balochistan, on 28 May 1998, after India's tests earlier that month.", "28 May is observed as Youm-e-Takbeer.", [297]),
(S, "In which Hijri year did Pakistan come into being (14 August 1947)?", ["1365 AH", "1366 AH", "1367 AH", "1368 AH"], 1, "14 August 1947 fell in Ramadan 1366 AH.", "It was the 27th of Ramadan, though some candidates remember it as 17 Ramadan.", [261, 263]),
(S, "If 4 June is Sunday, what day of the week will 15 June be?", ["Wednesday", "Thursday", "Friday", "Saturday"], 1, "From 4 June to 15 June is 11 days. 11 = 7 + 4, so the day is 4 days after Sunday, which is Thursday.", "The days repeat every 7 days.", [213]),
(S, "What is the area of a triangle with base 6 cm and height 5 cm?", ["30 sq cm", "11 sq cm", "15 sq cm", "20 sq cm"], 2, "Area = half x base x height = 0.5 x 6 x 5 = 15 sq cm.", "A triangle has half the area of a rectangle with the same base and height.", [92]),
(S, "What does GHQ stand for, and in which city is it located?", ["General Headquarters, Rawalpindi", "Grand Headquarters, Islamabad", "General Head Quarter, Lahore", "Government Headquarters, Karachi"], 0, "GHQ means General Headquarters, the headquarters of the Pakistan Army, located in Rawalpindi.", "The Chief of Army Staff works from GHQ.", [386, 412]),
(S, "Who is the Director General of ISI (Inter-Services Intelligence) of Pakistan as of 2026?", ["Lt Gen Nadeem Anjum", "Lt Gen Faiz Hameed", "Lt Gen Asim Malik", "Lt Gen Ahmed Sharif Chaudhry"], 2, "Lt Gen Muhammad Asim Malik has been DG ISI since September 2024 and was still in the post in 2026.", "His predecessor was Lt Gen Nadeem Anjum.", [124]),
]
